package com.enterprise.licensing.server.security;
import com.enterprise.licensing.engine.activation.LicenseRepository;import com.enterprise.licensing.engine.audit.AuditService;import com.enterprise.licensing.model.*;import com.fasterxml.jackson.databind.ObjectMapper;import jakarta.servlet.*;import jakarta.servlet.http.*;import java.io.IOException;import java.util.Map;import org.springframework.core.annotation.Order;import org.springframework.stereotype.Component;import org.springframework.web.filter.OncePerRequestFilter;import org.springframework.web.util.ContentCachingResponseWrapper;
@Component @Order(1)public final class AuditDecisionFilter extends OncePerRequestFilter{private final AuditService audit;private final LicenseRepository licenses;private final ObjectMapper mapper;public AuditDecisionFilter(AuditService a,LicenseRepository l,ObjectMapper m){audit=a;licenses=l;mapper=m;}@Override protected boolean shouldNotFilter(HttpServletRequest r){return !r.getRequestURI().startsWith("/api/v1/license");}@Override protected void doFilterInternal(HttpServletRequest request,HttpServletResponse response,FilterChain chain)throws ServletException,IOException{var wrapped=new ContentCachingResponseWrapper(response);try{chain.doFilter(request,wrapped);}finally{if(!Boolean.TRUE.equals(request.getAttribute(DomainDecisionAudit.RECORDED_ATTRIBUTE))){byte[]body=wrapped.getContentAsByteArray();boolean allowed=wrapped.getStatus()<400;LicenseReasonCode reason=allowed?LicenseReasonCode.LICENSE_VALID:LicenseReasonCode.INTERNAL_ERROR;try{var root=mapper.readTree(body);allowed=root.path("success").asBoolean(allowed);String code=root.path("reasonCode").asText();if(!code.isBlank())reason=LicenseReasonCode.valueOf(code);}catch(Exception ignored){}var state=licenses.active();String customer=state.map(s->s.license().customer().customerId()).orElse(null),license=state.map(s->s.license().licenseId()).orElse(null);audit.record(customer,license,request.getHeader("X-License-Instance-Id"),operation(request),request.getRequestURI(),allowed,reason,Map.of("method",request.getMethod(),"path",request.getRequestURI(),"httpStatus",Integer.toString(wrapped.getStatus())));}wrapped.copyBodyToResponse();}}
 private static LicenseOperation operation(HttpServletRequest r){String p=r.getRequestURI();if(p.contains("/activation/request"))return LicenseOperation.ACTIVATION_REQUEST;if(p.contains("/activation/import"))return LicenseOperation.ACTIVATION_IMPORT;if(p.contains("/instances/register"))return LicenseOperation.INSTANCE_REGISTER;if(p.contains("/instances/")&&r.getMethod().equals("DELETE"))return LicenseOperation.INSTANCE_DECOMMISSION;if(p.contains("/instances/"))return LicenseOperation.INSTANCE_TRANSITION;if(p.contains("/users/named")&&r.getMethod().equals("POST"))return LicenseOperation.NAMED_USER_ASSIGN;if(p.contains("/users/named"))return LicenseOperation.NAMED_USER_RELEASE;if(p.contains("/leases/users")&&p.endsWith("heartbeat"))return LicenseOperation.USER_LEASE_HEARTBEAT;if(p.contains("/leases/users"))return r.getMethod().equals("POST")?LicenseOperation.USER_LEASE_ACQUIRE:LicenseOperation.USER_LEASE_RELEASE;if(p.contains("/leases/agents")&&p.endsWith("heartbeat"))return LicenseOperation.AGENT_LEASE_HEARTBEAT;if(p.contains("/leases/agents"))return r.getMethod().equals("POST")?LicenseOperation.AGENT_LEASE_ACQUIRE:LicenseOperation.AGENT_LEASE_RELEASE;if(p.endsWith("/agents"))return LicenseOperation.AGENT_REGISTER;if(p.contains("/agents/"))return LicenseOperation.AGENT_REMOVE;if(p.contains("/features/"))return LicenseOperation.FEATURE_CHECK;if(p.contains("/entitlements/products/"))return LicenseOperation.PRODUCT_CHECK;if(p.endsWith("/usage"))return LicenseOperation.USAGE_CONSUME;if(p.endsWith("/cached-entitlements"))return LicenseOperation.CACHED_ENTITLEMENT_ISSUE;if(p.endsWith("/status")||p.endsWith("/entitlements")||p.endsWith("/audit"))return LicenseOperation.STATUS;return LicenseOperation.STATUS;}}
